/**
 * Receipt OCR Parser Utility
 * Role: Extracts structured financial details (merchant, total amount, date, category, note, breakdown)
 * from raw OCR text generated by on-device or fallback OCR engines.
 * Accurately handles both single-transaction receipts and multi-category receipts.
 */

import { EXPENSE_CATEGORIES } from '../models/TransactionModel.js';

/**
 * Maps section or keyword text to one of the 8 standard expense categories.
 * @param {string} text
 * @returns {string}
 */
export function mapToCategory(text) {
  if (!text || typeof text !== 'string') return 'Other';
  const t = text.toLowerCase();

  if (/grocery|groceries|food|beverage|snack|dining|restaurant|meal|bakery|fruit|veg|eat|kitchen|drink/i.test(t)) {
    return 'Food';
  }
  if (/personal\s*care|pharmacy|health|medical|drug|shampoo|soap|cosmetic|care|doctor|clinic/i.test(t)) {
    return 'Health';
  }
  if (/apparel|clothing|cloth|fashion|shoes|shopping|merchandise|retail|mall|zara|h&m/i.test(t)) {
    return 'Shopping';
  }
  if (/transport|fuel|petrol|diesel|cab|taxi|uber|ola|metro|rail|bus|transit|toll|parking|auto/i.test(t)) {
    return 'Transport';
  }
  if (/bill|utility|electric|water|gas|wifi|broadband|internet|recharge|dth/i.test(t)) {
    return 'Bills';
  }
  if (/cinema|movie|theatre|game|gaming|entertainment|ticket|show|concert/i.test(t)) {
    return 'Entertainment';
  }
  if (/rent|housing|maintenance|lease/i.test(t)) {
    return 'Rent';
  }
  if (/household|detergent|clean|home|hardware|cleaning/i.test(t)) {
    return 'Other';
  }

  return 'Other';
}

/**
 * Parses raw receipt text into structured expense data.
 * @param {string} rawText - Full OCR text output
 * @returns {Object} { merchant, amount, date, category, note, breakdown }
 */
export function parseReceiptText(rawText) {
  if (!rawText || typeof rawText !== 'string') {
    return {
      merchant: 'Store Receipt',
      amount: 0,
      date: '',
      category: 'Other',
      note: '',
      breakdown: []
    };
  }

  const lines = rawText.split('\n').map(l => l.trim()).filter(Boolean);

  // 1. Merchant Extraction
  let merchant = 'Store Receipt';
  for (let i = 0; i < Math.min(lines.length, 6); i++) {
    const line = lines[i];
    // Skip telephone, dates, receipt banners
    if (/^\+?[\d\s-]{7,}$/.test(line)) continue;
    if (/\d{1,2}[\/\.-]\d{1,2}[\/\.-]\d{2,4}/.test(line)) continue;
    if (/invoice|tax invoice|cash bill|welcome/i.test(line)) continue;
    if (/smart expense receipt|expense receipt/i.test(line)) continue;

    if (line.length >= 3 && /[a-zA-Z]/.test(line)) {
      // Strip leading prefixes like "Store Name:", "Shop:", "Merchant:"
      let cleaned = line.replace(/^(store\s*name|shop\s*name|merchant\s*name|store|shop|merchant|vendor)[\s:]+/i, '').trim();
      cleaned = cleaned.replace(/[^a-zA-Z0-9\s&'-]/g, '').trim();

      if (cleaned.length >= 3 && !/smart expense receipt/i.test(cleaned)) {
        merchant = cleaned;
        break;
      }
    }
  }

  // 2. Multi-Category Breakdown Detection (Subtotals by Department/Category)
  const breakdown = [];
  const subtotalRegex = /subtotal\s*(?:\(([^)]+)\)|:\s*([a-zA-Z\s&]+))?[:\s]*([^\d]*)([\d,]+(?:\.\d{1,2})?)/i;

  for (const line of lines) {
    const match = line.match(subtotalRegex);
    if (match) {
      const rawName = (match[1] || match[2] || 'Department').trim();
      let rawVal = match[4].replace(/,/g, '');
      let num = parseFloat(rawVal);

      // Clean leading OCR misread symbols (e.g. '7' misread for rupee symbol ₹ or bullet)
      if (rawVal.startsWith('7') && rawVal.length >= 4) {
        const alt = parseFloat(rawVal.substring(1));
        if (!isNaN(alt) && alt > 0) num = alt;
      }

      if (!isNaN(num) && num > 0) {
        const cat = mapToCategory(rawName);
        breakdown.push({
          name: rawName,
          category: cat,
          amount: parseFloat(num.toFixed(2))
        });
      }
    }
  }

  // 3. Amount Extraction (Tiered Bottom-Up Ranking)
  let amount = 0;

  // Tier 1: Grand Total, Final Total, Amount Payable, Net Total, Bill Total, Amount Paid
  const tier1Regex = /(?:grand\s*total|final\s*total|total\s*payable|amount\s*payable|net\s*payable|amount\s*paid|balance\s*due)[\s:]*([^\d]*)([\d,]+(?:\.\d{1,2})?)/i;
  // Tier 2: Total Amount, Net Amount, Bill Total, Total (Rs), Total (INR), Total (₹), Total ($)
  const tier2Regex = /(?:total\s*amount|total\s*amt|net\s*amount|net\s*total|bill\s*total|total\s*\([^)]+\)|total\s*\(rs\.?\)|total\s*\(inr\))[\s:]*([^\d]*)([\d,]+(?:\.\d{1,2})?)/i;
  // Exclusion regex for non-grand-total lines
  const excludeRegex = /(?:subtotal|sub\s*total|items|item|qty|quantity|count|pcs|tax|gst|cgst|sgst|discount|change|tendered|savings)/i;

  // Search Tier 1 from bottom of receipt up
  for (let i = lines.length - 1; i >= 0; i--) {
    const match = lines[i].match(tier1Regex);
    if (match) {
      const val = parseFloat(match[2].replace(/,/g, ''));
      if (!isNaN(val) && val > 0) {
        amount = val;
        break;
      }
    }
  }

  // Search Tier 2 if not found
  if (!amount) {
    for (let i = lines.length - 1; i >= 0; i--) {
      const match = lines[i].match(tier2Regex);
      if (match) {
        const val = parseFloat(match[2].replace(/,/g, ''));
        if (!isNaN(val) && val > 0) {
          amount = val;
          break;
        }
      }
    }
  }

  // Search Tier 3 (clean Total line excluding items/subtotals) if still not found
  if (!amount) {
    for (let i = lines.length - 1; i >= 0; i--) {
      const line = lines[i];
      if (/\btotal\b/i.test(line) && !excludeRegex.test(line)) {
        const numMatches = line.match(/(?:[\d,]+(?:\.\d{1,2})?)/g);
        if (numMatches && numMatches.length > 0) {
          const lastVal = parseFloat(numMatches[numMatches.length - 1].replace(/,/g, ''));
          if (!isNaN(lastVal) && lastVal > 0) {
            amount = lastVal;
            break;
          }
        }
      }
    }
  }

  // Cross-check: If breakdown subtotals sum up to more than a tiny extracted amount, sum them
  if (breakdown.length > 0) {
    const sumSubtotals = breakdown.reduce((sum, b) => sum + b.amount, 0);
    if (!amount || amount < sumSubtotals * 0.8) {
      // Grand total should be at least sum of subtotals
      amount = sumSubtotals;
    }
  }

  // Tier 4 fallback: Largest realistic number
  if (!amount) {
    let maxFound = 0;
    for (const line of lines) {
      if (excludeRegex.test(line)) continue;
      const matches = line.match(/(?:₹|Rs\.?|\$)?\s*(\d+(?:\.\d{2}))/g);
      if (matches) {
        for (const m of matches) {
          const val = parseFloat(m.replace(/[^0-9.]/g, ''));
          if (!isNaN(val) && val > maxFound && val < 1000000 && val !== 2024 && val !== 2025 && val !== 2026) {
            maxFound = val;
          }
        }
      }
    }
    amount = maxFound;
  }

  // 4. Date Extraction
  let date = '';
  for (const line of lines) {
    // DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
    const dmy = line.match(/\b(\d{1,2})[\/\.-](\d{1,2})[\/\.-](\d{2,4})\b/);
    if (dmy) {
      let day = dmy[1].padStart(2, '0');
      let month = dmy[2].padStart(2, '0');
      let year = dmy[3];
      if (year.length === 2) year = '20' + year;
      // Handle Month > 12 if formatted as MM/DD/YYYY
      if (Number(month) > 12 && Number(day) <= 12) {
        const temp = day;
        day = month;
        month = temp;
      }
      date = `${year}-${month}-${day}`;
      break;
    }

    // YYYY-MM-DD
    const ymd = line.match(/\b(20\d{2})[\/\.-](\d{1,2})[\/\.-](\d{1,2})\b/);
    if (ymd) {
      date = `${ymd[1]}-${ymd[2].padStart(2, '0')}-${ymd[3].padStart(2, '0')}`;
      break;
    }
  }

  // 5. Category Selection
  let category = 'Other';
  if (breakdown.length > 0) {
    // Compute total spend per mapped category to choose the top one
    const catSums = {};
    for (const item of breakdown) {
      catSums[item.category] = (catSums[item.category] || 0) + item.amount;
    }
    let topCat = 'Food';
    let topSum = 0;
    for (const [c, s] of Object.entries(catSums)) {
      if (s > topSum) {
        topSum = s;
        topCat = c;
      }
    }
    category = topCat;
  } else {
    // Fallback to text keywords
    category = mapToCategory(rawText);
  }

  // 6. Note Generation
  let note = merchant;
  if (breakdown.length > 1) {
    const parts = breakdown.map(b => `${b.name}: ₹${b.amount}`);
    note = `${merchant} (${parts.join(', ')})`;
  } else {
    note = `${merchant} (${category})`;
  }

  return {
    merchant,
    amount: parseFloat(Number(amount).toFixed(2)),
    date,
    category,
    note,
    breakdown
  };
}
